import{_ as n,c as t,o as d,ah as o}from"./chunks/framework.BjIn8lrq.js";const g=JSON.parse('{"title":"33. Frontend","description":"","frontmatter":{},"headers":[],"relativePath":"manual/teil-c-entwicklungs-systemdokumentation/33-frontend.md","filePath":"manual/teil-c-entwicklungs-systemdokumentation/33-frontend.md"}'),r={name:"manual/teil-c-entwicklungs-systemdokumentation/33-frontend.md"};function i(s,e,a,c,l,u){return d(),t("div",null,[...e[0]||(e[0]=[o('<h1 id="_33-frontend" tabindex="-1">33. Frontend <a class="header-anchor" href="#_33-frontend" aria-label="Permalink to &quot;33. Frontend&quot;">​</a></h1><p>Dieses Kapitel beschreibt die Weboberfläche von innen: wie sie aufgebaut ist, wie sie Daten holt und hält, wie Karte und Diagramme entstehen und wie Sprache, Gestaltung und Einstellungen funktionieren. Wie Sie das Frontend lokal starten, beschreibt Abschnitt <a href="./30-entwicklungsumgebung.html#_30-3-frontend-starten">Frontend starten</a>. Alle Pfade sind relativ zu <code>frontend/</code>.</p><h2 id="_33-1-sveltekit-struktur-und-routen" tabindex="-1">33.1 SvelteKit-Struktur und Routen <a class="header-anchor" href="#_33-1-sveltekit-struktur-und-routen" aria-label="Permalink to &quot;33.1 SvelteKit-Struktur und Routen&quot;">​</a></h2><p>Das Frontend ist eine SvelteKit-Anwendung mit Svelte 5 und TypeScript. Es läuft mit <code>@sveltejs/adapter-node</code> als eigener Node-Prozess und rendert jede Seite beim ersten Aufruf auf dem Server vor. Zwei experimentelle Schalter sind eingeschaltet (<code>svelte.config.js</code>): <code>kit.experimental.remoteFunctions</code> für die Remote Functions, siehe Abschnitt <a href="#_33-2-zustandsverwaltung-kontexte-und-remote-functions">Zustandsverwaltung</a>, und <code>compilerOptions.experimental.async</code> für <code>await</code> in Komponenten.</p><p>Unter <code>src/routes/</code> liegt je Menüpunkt eine Route, mit dem Pfad aus der Navigationsleiste:</p><table tabindex="0"><thead><tr><th>Route</th><th>Ansicht</th></tr></thead><tbody><tr><td><code>dashboard/[[projectId]]/[[flagId]]</code></td><td>Dashboard</td></tr><tr><td><code>map/[[projectId]]</code></td><td>Karte</td></tr><tr><td><code>fault-simulation/[[projectId]]</code>, <code>post-compaction</code>, <code>pipeline-records</code>, <code>valuation/[[projectId]]</code></td><td>Störungsanalyse, Nachverdichtung, Leitungsauskunft, Wertermittlung</td></tr><tr><td><code>conduit/[[projectId]]</code>, <code>trench/[[projectId]]/[[flagId]]</code>, <code>pipe-branch/[[projectId]]</code>, <code>house-connections/[[projectId]]</code></td><td>Rohrverwaltung, Rohrzuordnung, Rohrverzweigung, Mikrorohre</td></tr><tr><td><code>network-schema/[[projectId]]</code>, <code>trace/…</code></td><td>Netzschema, Faserweg</td></tr><tr><td><code>address/[projectId]/…</code></td><td>Adressen</td></tr><tr><td><code>settings</code>, <code>admin/logs</code></td><td>Einstellungen, Logs</td></tr><tr><td><code>login</code>, <code>logout</code></td><td>Anmeldung und Abmeldung</td></tr></tbody></table><p>Die Projektnummer steht als optionaler Parameter (<code>[[projectId]]</code>) im Pfad, bei den Adressen als Pflichtparameter (<code>[projectId]</code>). Ruft jemand eine Ansicht ohne sie auf, ergänzt der Server-Hook <code>handleProjectRedirect</code> sie aus dem Cookie <code>selected-project</code>; <code>/</code> leitet auf <code>/map</code> weiter. <code>src/routes/api/</code> enthält zwei eigene Server-Endpunkte für die Faserverbindungen einer Adresse bzw. Wohneinheit, keinen allgemeinen Durchgang zum Backend.</p><p>Fast jede Seite hat eine <code>+page.server.ts</code>, die ihre Daten auf dem Server lädt; Formularaktionen (<code>actions</code>) speichern dort, wo eine Seite ein klassisches Formular hat. Die Wurzel <code>+layout.server.ts</code> lädt für jede Seite die Projekte, die Kennzeichen, die Konfiguration vom Endpunkt <code>config/</code> des Backends (Koordinatenbezugssystem und seine Definition für proj4) und die Version der Anwendung.</p><p><strong>Wie das Frontend das Backend aufruft.</strong> Es gibt keinen generierten Client; der Code ruft <code>fetch</code> direkt auf, auf den beiden Wegen aus Abschnitt <a href="./29-architekturueberblick.html#_29-1-komponenten-und-weg-einer-anfrage">Komponenten und Weg einer Anfrage</a>. Auf dem Server reicht <code>getAuthHeaders()</code> (<code>src/lib/utils/getAuthHeaders.ts</code>) das Zugangstoken <code>api-access-token</code> aus der Anfrage des Browsers als <code>Cookie</code>-Header weiter; im Browser schickt <code>credentials: &#39;include&#39;</code> die Anmelde-Cookies mit.</p><p>Die Typen der Antworten kommen aus <code>src/lib/types/api.d.ts</code>, die openapi-typescript aus dem Schema des Backends erzeugt, siehe Abschnitt <a href="./32-rest-api.html#_32-7-openapi-schema-und-typgenerierung">OpenAPI-Schema und Typgenerierung</a>. <code>src/lib/types/index.ts</code> gibt ihnen kürzere Namen. Die Typen prüfen nur zur Entwicklungszeit; eine Prüfung der Antworten zur Laufzeit findet nicht statt.</p><p>Unbehandelte Fehler im Browser schickt <code>src/hooks.client.ts</code> an <code>logs/frontend/</code> des Backends; sie erscheinen in den Protokollen mit der Quelle „Frontend“, siehe Abschnitt <a href="./../teil-b-betrieb-admin-qgis/28-betrieb-der-instanz.html#_28-5-protokolle-auswerten">Protokolle auswerten</a>.</p><p><code>src/service-worker.ts</code> und <code>static/manifest.webmanifest</code> machen die Anwendung im Browser installierbar. Der Service Worker speichert nichts zwischen; ohne Verbindung zum Server funktioniert die Anwendung nicht.</p><h2 id="_33-2-zustandsverwaltung-kontexte-und-remote-functions" tabindex="-1">33.2 Zustandsverwaltung, Kontexte und Remote Functions <a class="header-anchor" href="#_33-2-zustandsverwaltung-kontexte-und-remote-functions" aria-label="Permalink to &quot;33.2 Zustandsverwaltung, Kontexte und Remote Functions&quot;">​</a></h2><p>Die Komponenten nutzen durchgehend die <strong>Runes</strong> von Svelte 5 (<code>$state</code>, <code>$derived</code>, <code>$effect</code>, <code>$props</code>); die Schreibweise von Svelte 4 (<code>export let</code>, <code>$:</code>) kommt nicht mehr vor. Für Zustand, der über eine Komponente hinausgeht, gibt es drei Mittel nebeneinander:</p><ul><li><strong>Zustandsklassen</strong> in <code>src/lib/classes/*.svelte.ts</code> – Klassen mit <code>$state</code>-Feldern, die den Zustand und die Logik einer Ansicht bündeln: <code>MapState</code> und die <code>Map…Manager</code> der Karte, <code>NetworkSchemaState</code> mit seinen Managern, <code>NodeStructureManager</code>, <code>FiberSpliceManager</code>, <code>DragDropManager</code> für die Netzknotenstruktur, <code>ConduitState</code>, <code>AddressState</code>, <code>TrenchProfileState</code> und andere. Logik, die mehr als eine Komponente braucht, liegt in diesen Klassen.</li><li><strong>Kontexte</strong> – eine Ansicht erzeugt ihre Zustandsklassen einmal und reicht sie mit <code>setContext</code> an ihre Komponenten weiter. Das Netzschema nutzt dafür typisierte Kontexte aus <code>src/lib/context/networkSchemaContext.ts</code>, die übrigen Ansichten Zeichenketten als Schlüssel (<code>&#39;mapManagers&#39;</code>, <code>&#39;conduitState&#39;</code> …). Einige Routen bringen eigene Kontextmodule mit, etwa <code>src/routes/trace/traceMapContext.svelte.ts</code>.</li><li><strong>Stores</strong> in <code>src/lib/stores/</code> – die Stores von Svelte für alles, was über Ansichten hinweg gilt: das ausgewählte Projekt, die Info-Box (<code>drawer.ts</code>), Meldungen (<code>toaster.ts</code>), das angemeldete Konto (<code>auth.ts</code>) und die Einstellungen in <code>store.ts</code>, siehe Abschnitt <a href="#_33-7-benutzereinstellungen-und-deren-speicherung">Benutzereinstellungen und deren Speicherung</a>.</li></ul><p><strong>Remote Functions</strong> von SvelteKit liegen in <code>src/lib/remote/network-schema/*.remote.ts</code>. Genutzt werden sie vom Netzschema und von der Info-Box der Karte: von ihrer Kabelliste (<code>CableTrenchDataManager</code>) und von der Netzknotenstruktur, die die Info-Box aus dem Netzschema übernimmt (<code>NodeStructurePanel</code>, <code>NodeSlotConfigPanel</code>). Lesende Funktionen sind <code>query</code>, schreibende <code>command</code>; ihre Eingaben prüft valibot. Sie laufen auf dem Server und rufen das Backend über <code>API_URL</code> auf; die Anmeldung holt <code>djangoHeaders()</code> in <code>remote-auth.ts</code> über <code>getRequestEvent()</code> aus der laufenden Anfrage. Alle anderen Ansichten arbeiten mit Lade-Funktionen, Formularaktionen und <code>fetch</code> im Browser.</p><div class="warning custom-block"><p class="custom-block-title">Wichtig</p><p>Remote Functions sind in SvelteKit zum Stand des Handbuchs experimentell. Ihre Schnittstelle kann sich mit einer neuen Version von SvelteKit ändern; prüfen Sie bei einer Aktualisierung von <code>@sveltejs/kit</code> das Netzschema sowie Kabelliste und Netzknotenstruktur in der Info-Box der Karte zuerst.</p></div><h2 id="_33-3-kartenintegration-mit-openlayers" tabindex="-1">33.3 Kartenintegration mit OpenLayers <a class="header-anchor" href="#_33-3-kartenintegration-mit-openlayers" aria-label="Permalink to &quot;33.3 Kartenintegration mit OpenLayers&quot;">​</a></h2><p>Die Karte ist OpenLayers 10, aufgebaut in <code>src/lib/components/Map.svelte</code>; die Logik für Auswahl, Info-Box, Messen und Hervorheben liegt in den Klassen <code>MapState</code>, <code>MapInteractionManager</code>, <code>MapSelectionManager</code>, <code>MapPopupManager</code> und <code>MapMeasureManager</code>. Der Faserweg hat eine eigene Karte (<code>src/routes/trace/components/TraceMap.svelte</code>). Was in der Karte zu sehen ist, stammt aus drei Quellen, siehe Abschnitt <a href="./29-architekturueberblick.html#_29-1-komponenten-und-weg-einer-anfrage">Komponenten und Weg einer Anfrage</a>.</p><p><strong>Hintergrundkarte.</strong> <code>ol-mapbox-style</code> wendet den Stil <code>${PUBLIC_TILE_SERVER_URL}/styles/light/style.json</code> bzw. <code>…/dark/…</code> auf die Karte an. Ist der Kachelserver nicht erreichbar oder die Variable leer, fällt die Karte auf Rasterkacheln von OpenStreetMap zurück und hält das im Store <code>tileServerAvailable</code> fest, siehe auch Abschnitt <a href="./../teil-b-betrieb-admin-qgis/28-betrieb-der-instanz.html#_28-6-kartenkacheln-bereitstellen-und-erneuern">Kartenkacheln bereitstellen und erneuern</a>.</p><p><strong>Netzobjekte.</strong> Trassen, Netzknoten, Adressen und Gebiete kommen als Vektorkacheln vom Backend (<code>src/lib/map/tileSources.ts</code>), siehe Abschnitt <a href="./32-rest-api.html#_32-6-vektor-tile-endpunkte">Vektor-Tile-Endpunkte</a>. Ihre Verarbeitung ist auf Geschwindigkeit ausgelegt:</p><ul><li>Eine Kachel wird nicht im Hauptthread entpackt, sondern in einem Pool von Web Workern (<code>workerPool.ts</code>, <code>mvtParserWorker.ts</code>), mit so vielen Workern, wie der Rechner Kerne hat, höchstens vier. <code>featureReconstructor.ts</code> baut aus dem Ergebnis die Objekte für OpenLayers.</li><li>Wechselt jemand die Seite, bricht <code>navigationCancellation.ts</code> alle laufenden Kachelanfragen ab; <code>tileLoadingManager.ts</code> hält dafür die <code>AbortController</code> der Anfragen.</li><li>Antwortet das Backend auf eine Kachel mit 401, ruft die Kachel <code>invalidateAll()</code> auf, damit der Server-Hook den Token erneuert, und wiederholt die Anfrage einmal, siehe Abschnitt <a href="#_33-8-anmeldung-token-erneuerung-und-routenschutz-im-frontend">Anmeldung, Token-Erneuerung und Routenschutz im Frontend</a>.</li></ul><p>GeoJSON nutzt die Karte nur für Ebenen, die eine Ansicht selbst erzeugt: Suchtreffer, Faserweg, Störungsanalyse, Nachverdichtung, Auskunftsbereiche, Wertermittlung.</p><p><strong>WMS-Ebenen.</strong> <code>TileWMS</code> in <code>src/lib/map/layers.ts</code> lädt die Bilder über den WMS-Proxy des Backends in Kacheln von 512 Pixeln in EPSG:3857. Quellen und Layer liest <code>src/lib/utils/wmsApi.ts</code> aus der Schnittstelle; den kurzlebigen Token für die Kachelanfragen hält <code>wmsTokenHeartbeat.svelte.ts</code> frisch.</p><p><strong>Projektion.</strong> Die Karte zeigt Web Mercator. Geometrien, die das Backend im Koordinatenbezugssystem der Installation liefert – Suchtreffer, Auskunftsbereiche der Leitungsauskunft, Wertermittlung –, rechnet sie mit proj4 um; <code>src/lib/map/projectionUtils.ts</code> registriert dafür die Definition vom Endpunkt <code>config/</code>.</p><p><strong>Stile.</strong> Wie die Objekte aussehen, legt <code>src/lib/map/styles.ts</code> fest, mit den Vorgabefarben aus <code>defaultColors.ts</code>; die Einstellungen der Nutzenden aus Kapitel <a href="./../teil-a-anwenderhandbuch/17-einstellungen.html">Einstellungen</a> überschreiben sie.</p><h2 id="_33-4-diagramm-und-canvas-ansichten" tabindex="-1">33.4 Diagramm- und Canvas-Ansichten <a class="header-anchor" href="#_33-4-diagramm-und-canvas-ansichten" aria-label="Permalink to &quot;33.4 Diagramm- und Canvas-Ansichten&quot;">​</a></h2><p>Drei Ansichten zeichnen Knoten und Kanten mit <strong>Svelte Flow</strong> (<code>@xyflow/svelte</code>):</p><ul><li>das <strong>Netzschema</strong> (<code>src/routes/network-schema/[[projectId]]</code>) mit eigenen Knoten und Kanten für Netzknoten und Kabel (<code>CableDiagramNode</code>, <code>CableDiagramEdge</code>, <code>DynamicEdgeLabel</code>) und das Unternetz eines Netzknotens (<code>…/node/[nodeId]</code>),</li><li>die <strong>Rohrverzweigung</strong> (<code>src/routes/pipe-branch/[[projectId]]</code>) mit eigenen Knoten und Kanten für Rohre und Mikrorohre und einer Lasso-Auswahl, die auf ein eigenes Canvas zeichnet (<code>PipeBranchLasso.svelte</code>),</li><li>das <strong>Grabenprofil</strong> einer Trasse in der Karte (<code>src/routes/map/[[projectId]]/TrenchProfile*.svelte</code>).</li></ul><p>Die Lage der Knoten im Netzschema speichert das Backend (<code>canvas_x</code>, <code>canvas_y</code> am Netzknoten, <code>diagram_path</code> am Kabel, siehe Abschnitt <a href="./31-datenmodell-des-backends.html#_31-4-kabel-faser-spleiß">Kabel, Faser, Spleiß</a>); der Ausschnitt, den jemand gerade betrachtet, steht im Browser (<code>networkSchemaViewport</code>).</p><p>Die <strong>Netzknotenstruktur</strong> – Steckplätze, Komponenten, Ports, Spleiße – ist dagegen kein Svelte-Flow-Diagramm, sondern gewöhnliches HTML; das Ziehen und Ablegen übernimmt <code>DragDropManager</code>.</p><p>Die <strong>Diagramme</strong> des Dashboards zeichnet Chart.js, gekapselt in <code>src/lib/components/Chart.svelte</code>, <code>DonutChart.svelte</code> und <code>StackedBarChart.svelte</code>. Die PDF-Dokumente der Nachverdichtung und der Adressen entstehen mit jsPDF im Browser.</p><h2 id="_33-5-internationalisierung-mit-paraglide" tabindex="-1">33.5 Internationalisierung mit Paraglide <a class="header-anchor" href="#_33-5-internationalisierung-mit-paraglide" aria-label="Permalink to &quot;33.5 Internationalisierung mit Paraglide&quot;">​</a></h2><p>Die Texte der Oberfläche übersetzt Paraglide 2. Die Einstellungen stehen in <code>project.inlang/settings.json</code>: Ausgangssprache Deutsch (<code>baseLocale: &quot;de&quot;</code>), Sprachen <code>de</code> und <code>en</code>, die Texte in <code>messages/de.json</code> und <code>messages/en.json</code>. Das Vite-Plugin übersetzt sie beim Bauen in Funktionen in <code>src/lib/paraglide/</code>, die nicht im Repository liegen; im Code steht ein Text als Aufruf, etwa <code>m.nav_dashboard()</code>.</p><p>Die Sprache bestimmt Paraglide über die Strategie <code>[&#39;localStorage&#39;, &#39;baseLocale&#39;]</code> (<code>vite.config.ts</code> und das Skript <code>paraglide</code> in <code>package.json</code>): zuerst den Schlüssel <code>PARAGLIDE_LOCALE</code> im <code>localStorage</code> des Browsers, sonst Deutsch. Daraus folgt:</p><ul><li>Der Server kennt <code>localStorage</code> nicht und rendert jede Seite <strong>auf Deutsch</strong>. Wer Englisch gewählt hat, sieht beim Laden kurz die deutsche Fassung, bis der Browser übernimmt.</li><li>Texte, die eine Lade-Funktion auf dem Server mit Paraglide erzeugt, bleiben deutsch. Die meisten Fehlermeldungen der Server-Seite stehen ohnehin fest auf Englisch im Code oder kommen vom Backend.</li><li>Die Sprache ist eine Einstellung des Browsers, nicht des Kontos, siehe Abschnitt <a href="#_33-7-benutzereinstellungen-und-deren-speicherung">Benutzereinstellungen und deren Speicherung</a>.</li></ul><p>Das Backend übersetzt seine eigenen Texte – den Administrationsbereich, Meldungen der Schnittstelle – unabhängig davon mit gettext von Django, siehe Abschnitt <a href="./36-erweitern-und-mitwirken.html#_36-3-eine-weitere-sprache-erganzen">Eine weitere Sprache ergänzen</a>.</p><div class="info custom-block"><p class="custom-block-title">Hinweis</p><p>Der Kommentar in <code>src/lib/utils/userSettingsSync.ts</code>, die Sprache liege in einem eigenen Cookie, stimmt zum Stand des Handbuchs nicht; sie liegt im <code>localStorage</code>.</p></div><h2 id="_33-6-designsystem-theming-und-komponenten" tabindex="-1">33.6 Designsystem, Theming und Komponenten <a class="header-anchor" href="#_33-6-designsystem-theming-und-komponenten" aria-label="Permalink to &quot;33.6 Designsystem, Theming und Komponenten&quot;">​</a></h2><p>Gestaltet ist die Oberfläche mit <strong>Tailwind CSS 4</strong> und <strong>Skeleton 5</strong> (<code>@skeletonlabs/skeleton</code>, <code>@skeletonlabs/skeleton-svelte</code>). Es gibt keine <code>tailwind.config</code>; Tailwind, das Formular-Plugin, Skeleton und dessen Theme <code>legacy</code> werden in <code>src/app.css</code> eingebunden, wo auch die Anpassungen für Svelte Flow und die Meldungen stehen. Die Symbole kommen aus <code>@tabler/icons-svelte</code>.</p><ul><li><strong>Theme</strong> – <code>+layout.svelte</code> schreibt das Theme aus dem Store <code>theme</code> in das Attribut <code>data-theme</code> von <code>&lt;html&gt;</code>.</li><li><strong>Hell und dunkel</strong> – die Tailwind-Variante <code>dark</code> gilt unter <code>[data-mode=&quot;dark&quot;]</code> (<code>@custom-variant dark</code> in <code>app.css</code>). <code>src/lib/components/LightSwitch.svelte</code> setzt das Attribut, speichert den Modus im Schlüssel <code>mode</code> des <code>localStorage</code> und setzt außerdem den Store <code>lightSwitchMode</code>. Gelesen wird nur <code>mode</code>. <code>lightSwitchMode</code> abonniert keine Komponente, und ein <code>persisted()</code>-Store schreibt erst in den <code>localStorage</code>, sobald er abonniert ist – der Schlüssel <code>lightSwitchMode</code> entsteht deshalb nie. Die Hintergrundkarte hat ihren eigenen Hell-Dunkel-Schalter (<code>basemapTheme</code>).</li></ul><p>Gemeinsame Komponenten liegen flach in <code>src/lib/components/</code>: Karte, Info-Box (<code>Drawer</code>), Navigationsleiste (<code>SideBar</code>, unterhalb von 768 Pixeln <code>MobileNav</code>), Kopfzeile (<code>AppBar</code>), Auswahllisten, Diagramme, Suchfelder. Was nur eine Ansicht braucht, liegt neben ihrer Route. Von Skeleton kommen vor allem die Bausteine für Dialoge, Reiter, Akkordeons, Menüs, Auswahllisten, Schalter, Schieberegler, Seitenwechsel, Datei-Uploads und Meldungen.</p><h2 id="_33-7-benutzereinstellungen-und-deren-speicherung" tabindex="-1">33.7 Benutzereinstellungen und deren Speicherung <a class="header-anchor" href="#_33-7-benutzereinstellungen-und-deren-speicherung" aria-label="Permalink to &quot;33.7 Benutzereinstellungen und deren Speicherung&quot;">​</a></h2><p>Die Einstellungen der Oberfläche liegen im <code>localStorage</code> des Browsers. <code>persisted()</code> in <code>src/lib/stores/persisted.ts</code> ist ein Store von Svelte, der seinen Wert beim ersten Abonnieren aus dem <code>localStorage</code> liest und jede Änderung dorthin zurückschreibt, als JSON unter einem festen Schlüssel. So sind in <code>src/lib/stores/store.ts</code> rund 35 Einstellungen angelegt: Kartenposition (<code>mapCenter</code>, <code>mapZoom</code>), Sichtbarkeit und Transparenz der Layer, Trassenfarben und Stile der Netzknotentypen, Adressen und Gebiete, Routing-Toleranz, Breite der Info-Box, Anzeigeoptionen des Netzschemas und mehr. <code>sidebarPreferences.ts</code> hält die ausgeblendeten Menüpunkte und eingeklappten Gruppen der Navigationsleiste. Zwei Ansichtszustände – das gewählte Rohr (<code>selectedConduit</code>) und ob die Legende der Karte aufgeklappt ist (<code>layerTreeExpanded</code>) – legt <code>session()</code> aus <code>session.ts</code> stattdessen im <code>sessionStorage</code> ab; sie gelten nur, solange der Tab offen ist.</p><p>Der <code>localStorage</code> gehört zur Adresse der Weboberfläche im Browser, nicht zum Konto. Melden sich zwei Personen nacheinander im selben Browser an, teilen sie die Einstellungen.</p><p><strong>Im Konto speichern.</strong> <code>src/lib/utils/userSettingsSync.ts</code> überträgt die Einstellungen auf Wunsch ins Backend, siehe Abschnitt <a href="./../teil-a-anwenderhandbuch/17-einstellungen.html#_17-2-einstellungen-im-konto-speichern-und-wieder-laden">Einstellungen im Konto speichern und wieder laden</a>:</p><ul><li><code>saveUserSettings()</code> liest die Schlüssel aus der Liste <code>SYNCED_SETTINGS_KEYS</code> aus dem <code>localStorage</code> und schickt sie mit <code>PUT user-settings/</code> an das Backend, das sie als JSON in <code>user_settings</code> ablegt.</li><li><code>loadUserSettings()</code> holt sie mit <code>GET user-settings/</code> und schreibt sie zurück in den <code>localStorage</code>.</li></ul><p>Übertragen wird nur, was in <code>SYNCED_SETTINGS_KEYS</code> steht. Kartenposition, Sprache und der Schlüssel <code>mode</code> gehören nicht dazu. Die Liste enthält zwar <code>lightSwitchMode</code>, aber weil die Oberfläche den Modus aus <code>mode</code> liest, folgt der Hell- oder Dunkelmodus dem Konto nicht. Eine neue Einstellung, die sich im Konto speichern lassen soll, braucht deshalb zwei Einträge: den <code>persisted()</code>-Store und den Schlüssel in der Liste. Das Speichern und Laden geschieht nur auf Knopfdruck; ein automatischer Abgleich zwischen Geräten findet nicht statt. Nach dem Laden lädt die Einstellungsseite die ganze Seite neu (<code>location.reload()</code>), weil die bereits abonnierten Stores den geänderten <code>localStorage</code> nicht von selbst lesen.</p><h2 id="_33-8-anmeldung-token-erneuerung-und-routenschutz-im-frontend" tabindex="-1">33.8 Anmeldung, Token-Erneuerung und Routenschutz im Frontend <a class="header-anchor" href="#_33-8-anmeldung-token-erneuerung-und-routenschutz-im-frontend" aria-label="Permalink to &quot;33.8 Anmeldung, Token-Erneuerung und Routenschutz im Frontend&quot;">​</a></h2><p>Die Anmeldung der Weboberfläche läuft über den Server des Frontends. Die Formularaktion in <code>src/routes/login/+page.server.ts</code> schickt Benutzername und Passwort an <code>auth/login/</code> des Backends, übernimmt die Cookies aus dessen Antwort und setzt sie für die eigene Antwort an den Browser. Fehlt das Cookie <code>selected-project</code>, setzt sie es auf 1.</p><p>Bei jeder Anfrage an den Server des Frontends laufen drei Hooks nacheinander (<code>src/hooks.server.ts</code>): Paraglide, <code>handleAuth</code> und <code>handleProjectRedirect</code>. <code>handleAuth</code></p><ol><li>fragt mit dem Zugangstoken aus dem Cookie <code>auth/user/</code> beim Backend ab,</li><li>erneuert bei 401 oder 403 die Tokens über <code>auth/token/refresh/</code> und übernimmt die neuen Cookies, dann fragt es erneut,</li><li>holt bei Erfolg die Rechte des Kontos über <code>auth/permissions/</code> und legt Konto und Rechte in <code>event.locals.user</code> ab,</li><li>löscht andernfalls beide Cookies und leitet auf <code>/login?redirectTo=…</code> weiter,</li><li>leitet auf <code>/map</code> weiter, wenn die Routenrechte den angefragten Pfad nicht erlauben.</li></ol><p>Jede Seitenanfrage kostet damit mindestens zwei Anfragen an das Backend, bevor die Seite selbst ihre Daten lädt.</p><p><strong>Erneuerung ohne Seitenwechsel.</strong> Der Zugangstoken gilt 15 Minuten. Bleibt jemand länger auf einer Seite, ohne zu navigieren, käme kein Hook zum Zug, und die Anfragen des Browsers liefen ins Leere. <code>src/lib/utils/tokenHeartbeat.svelte.ts</code> ruft deshalb alle sieben Minuten <code>invalidateAll()</code> auf: SvelteKit lädt die Daten der Seite neu, der Server-Hook läuft und erneuert die Tokens. Dieselbe Rolle spielt <code>invalidateAll()</code> in den Kachelanfragen und beim Speichern der Einstellungen, wenn das Backend mit 401 antwortet.</p><p><strong>Routenschutz.</strong> <code>canAccessRoute()</code> prüft einen Pfad gegen die Routenrechte aus <code>auth/permissions/</code>: erst ein genauer Treffer, dann Muster mit <code>/*</code>; was kein Muster erfasst, ist erlaubt. Die Funktion gibt es zweimal, im Server-Hook und in <code>src/lib/utils/permissions.ts</code> für die Navigationsleiste; ändern Sie beide gemeinsam. <code>permissions.ts</code> enthält außerdem <code>canView</code>, <code>canEdit</code> und <code>canDelete</code>, mit denen die Ansichten Schaltflächen nach den Modellrechten ein- und ausblenden.</p><p>Routenrechte prüft nur das Frontend; was eine Anfrage an die Schnittstelle darf, entscheidet das Backend, siehe Abschnitt <a href="./32-rest-api.html#_32-3-berechtigungsprufung-in-der-schnittstelle">Berechtigungsprüfung in der Schnittstelle</a>. Wie eine neue Route mit Menüpunkt und Recht entsteht, beschreibt Abschnitt <a href="./36-erweitern-und-mitwirken.html#_36-2-eine-neue-route-samt-berechtigung-erganzen">Eine neue Route samt Berechtigung ergänzen</a>.</p>',56)])])}const m=n(r,[["render",i]]);export{g as __pageData,m as default};
